const html = typeof $input.first().json.data === 'string' ? $input.first().json.data : ($input.first().json.body || JSON.stringify($input.first().json));
const text = html
  .replace(/<script[\s\S]*?<\/script>/gi, ' ')
  .replace(/<style[\s\S]*?<\/style>/gi, ' ')
  .replace(/<[^>]+>/g, ' ')
  .replace(/\s+/g, ' ')
  .trim()
  .slice(0, 14000);
const prev = $('Normalize Input').first().json;
return [{ json: { ...prev, jobText: text } }];

const item = $('Fit Score (OpenAI)').first().json;

const out = Array.isArray(item.output) ? item.output[0] : item.output;

const raw =
  (typeof out === 'string' ? out : null) ??
  out?.content?.[0]?.text ??
  out?.text ??
  null;

if (typeof raw !== 'string' || !raw.length) {
  throw new Error(
    'No text. outType=' +
      typeof out +
      ' outKeys=' +
      Object.keys(out || {}).join(',')
  );
}

const start = raw.indexOf('{');
const end = raw.lastIndexOf('}');
if (start < 0 || end < 0) {
  throw new Error('No JSON in text: ' + raw.slice(0, 160));
}

const fit = JSON.parse(raw.slice(start, end + 1));

if (typeof fit.fitScore !== 'number') {
  throw new Error('fitScore missing: ' + JSON.stringify(fit).slice(0, 160));
}

return [{
  json: {
    fitScore: fit.fitScore,
    title: fit.title,
    company: fit.company,
    location: fit.location,
    seniority: fit.seniority,
    stackMatch: fit.stackMatch,
    stackGaps: fit.stackGaps,
    liveCodingRisk: fit.liveCodingRisk,
    whyFit: fit.whyFit,
    risks: fit.risks,
    applyPriority: fit.applyPriority,
    reasoning: fit.reasoning,
    jobUrl: item.jobUrl,
    receivedAt: item.receivedAt,
    probe: 'parsed-ok',
  },
}];

const item = $('Draft Package').first().json; // ← your draft OpenAI node name

const out = Array.isArray(item.output) ? item.output[0] : item.output;
const raw =
  (typeof out === 'string' ? out : null) ??
  out?.content?.[0]?.text ??
  out?.text ??
  null;

if (typeof raw !== 'string' || !raw.length) {
  throw new Error('No draft text. keys=' + Object.keys(item).join(','));
}

const start = raw.indexOf('{');
const end = raw.lastIndexOf('}');
const draft = JSON.parse(raw.slice(start, end + 1));

const fit = $('Code in JavaScript').first().json; // ← your fit-parse Code node name

return [{
  json: {
    ...fit,
    ...draft,
  },
}];
